# Kaskad 3: site vhost.  Contains the private panel path; mode 0600.
# This file is included from nginx http {}, so the named zone is valid here.
limit_req_zone $binary_remote_addr zone=kaskad_pages:10m rate=5r/s;

server {
    listen 80;
    listen [::]:80;
    server_name domain.placeholder.example;
    location ^~ /.well-known/acme-challenge/ {
        root @ACME@;
    }
    location / {
        return 301 https://$server_name$request_uri;
    }
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name domain.placeholder.example;
    root @ROOT@;
    index index.html;
    ssl_certificate @CERT@;
    ssl_certificate_key @KEY@;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305';
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:kaskad_ssl:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains" always;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options SAMEORIGIN always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    server_tokens off;
    disable_symlinks on from=$document_root;

location ^~ /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ/ {
    proxy_pass http://unix:@SOCK@:/;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto https;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Prefix /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ;
    proxy_http_version 1.1;
    proxy_read_timeout 30m;
    proxy_send_timeout 30m;
    client_max_body_size 1m;
    access_log off;
    error_log /dev/null crit;
}
location = /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ/api/backup/preview {
    proxy_pass http://unix:@SOCK@:/api/backup/preview;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto https;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Prefix /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ;
    proxy_http_version 1.1;
    proxy_read_timeout 30m;
    proxy_send_timeout 30m;
    client_max_body_size 20m;
    access_log off;
    error_log /dev/null crit;
}
location = /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ/api/backup/import {
    proxy_pass http://unix:@SOCK@:/api/backup/import;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto https;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Prefix /app-QQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQQ;
    proxy_http_version 1.1;
    proxy_read_timeout 30m;
    proxy_send_timeout 30m;
    client_max_body_size 20m;
    access_log off;
    error_log /dev/null crit;
}

location ^~ /p/ {
    proxy_pass http://unix:@SOCK@:;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto https;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Prefix /;
    proxy_http_version 1.1;
    proxy_read_timeout 30m;
    proxy_send_timeout 30m;
    limit_req zone=kaskad_pages burst=40 nodelay;
    limit_req_status 404;
    access_log off;
    error_log /dev/null crit;
}

    # Guesses of a panel path look exactly like a missing page and are not logged.
    location ~ "^/(app-[A-Za-z0-9_-]{86}|app-[0-9a-f]{12,128})(/|$)" {
        access_log off;
        error_log /dev/null crit;
        return 404;
    }
    location ~ /\. {
        return 404;
    }
    location / {
        try_files $uri $uri/ =404;
    }
}

server {
    listen 443 ssl default_server;
    listen [::]:443 ssl default_server;
    ssl_reject_handshake on;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    access_log off;
    location ^~ /.well-known/acme-challenge/ {
        root @ACME@;
    }
    location / {
        return 444;
    }
}

